var body=$("body");var check_container=$("#payment_type-contaienr");var cart_table=$("#cart-table-container");body.on("keyup","#card-value",function(a){if(a.keyCode==13){discount("check","card")}});body.on("keyup","#coupon-value",function(a){if(a.keyCode==13){discount("check","coupon")}});body.on("click","#btn-card",function(){discount("check","card")});body.on("click","#btn-coupon",function(){discount("check","coupon")});body.on("click","#btn-remove-card",function(){discount("remove","card")});body.on("click","#btn-remove-coupon",function(){discount("remove","coupon")});body.on("change","#startcheckout-card_only",function(){ajaxit("post","/checkout/ajax/refresh-checkout-widget",check_container,{val:$(this).is(":checked")}).done(function(a){updateCheckNCart(a)})});body.on("change",".cart-table__quantity-changer",function(){var b=parseInt($(this).val()),a=$(this).parents(".vm").next();ajaxit("post","/checkout/ajax/change-quantity",check_container,{sku:$(this).data("sku"),quantity:b}).done(function(c){check_container.html(c);a.next().children("span").text(parseInt(a.children("span").text())*b)})});function discount(c,a){var b=null;if(c==="check"){b={};b[a]=$("#"+a+"-value").val()}ajaxit("post","/checkout/ajax/"+c+"-"+a,check_container,b).done(function(d){updateCheckNCart(d)})}function refreshCheckoutWidget(){ajaxit("post","/checkout/ajax/refresh-checkout-widget",check_container,null).done(function(a){updateCheckNCart(a)})}function updateCheckNCart(b){var c=JSON.parse(b);check_container.html(c.check);cart_table.html(c.list);var a=$("#card-value");a.inputmask({mask:"99999-99999"})};